const cds = require("@sap/cds");
const XLSX = require("xlsx");

const LOG = cds.log("requests-drafts-upload-items-logic");

const VALID_ASSET_STATUS = ["N", "A", "R"];
const MAX_ERRORS_SHOWN = 20;
const MAX_BASE64_LENGTH = 10 * 1024 * 1024;
const SR_NO_PAD_LENGTH = 3;

/**
 * Supported upload template columns.
 *
 * These must match the headers generated by items-template.js.
 */
const TEMPLATE_COLUMNS = [
  { key: "srNo", header: "SR No" },
  { key: "costCentre", header: "Cost Centre" },
  { key: "glAccount", header: "GL Account" },
  { key: "material", header: "Material" },
  { key: "wbs", header: "WBS" },
  { key: "assetStatus", header: "Asset Status" },
  { key: "supplementAmount", header: "Supplement Amount" },
  { key: "returnAmount", header: "Return Amount" },
  { key: "transferInAmount", header: "Transfer In Amount" },
  { key: "transferOutAmount", header: "Transfer Out Amount" },
  { key: "description", header: "Description" },
];

const AMOUNT_FIELDS = [
  "supplementAmount",
  "returnAmount",
  "transferInAmount",
  "transferOutAmount",
];

function normalizeHeader(value) {
  return String(value || "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, " ");
}

function buildHeaderMap() {
  const map = {};

  for (const col of TEMPLATE_COLUMNS) {
    map[normalizeHeader(col.header)] = col.key;
  }

  return map;
}

function parseExcel(base64Content) {
  const workbook = XLSX.read(base64Content, { type: "base64" });
  const sheetName = workbook.SheetNames[0];

  if (!sheetName) {
    return {
      rows: [],
      uploadedFields: [],
    };
  }

  const sheet = workbook.Sheets[sheetName];
  const rows = XLSX.utils.sheet_to_json(sheet, {
    header: 1,
    defval: "",
  });

  if (!rows || rows.length < 2) {
    return {
      rows: [],
      uploadedFields: [],
    };
  }

  const headerMap = buildHeaderMap();
  const headerRow = rows[0].map(function (header) {
    return normalizeHeader(header);
  });

  const colToField = headerRow.map(function (header) {
    return headerMap[header] || null;
  });

  const uploadedFields = colToField.filter(function (field) {
    return !!field;
  });

  const parsed = [];

  for (let i = 1; i < rows.length; i++) {
    const row = rows[i];

    const isEmpty = row.every(function (cell) {
      return cell === "" || cell === null || cell === undefined;
    });

    if (isEmpty) {
      continue;
    }

    const obj = {};

    row.forEach(function (cell, idx) {
      const field = colToField[idx];

      if (field) {
        obj[field] = typeof cell === "string" ? cell.trim() : cell;
      }
    });

    obj.__rowNumber = i + 1;
    parsed.push(obj);
  }

  return {
    rows: parsed,
    uploadedFields: uploadedFields,
  };
}

function hasField(uploadedFields, fieldName) {
  return uploadedFields.indexOf(fieldName) !== -1;
}

function toTrimmedString(value) {
  if (value === null || value === undefined || value === "") {
    return null;
  }

  return String(value).trim();
}

function parsePositiveAmount(row, fieldName, errors) {
  const rowNo = row.__rowNumber;
  const value = row[fieldName];

  if (value === "" || value === null || value === undefined) {
    return null;
  }

  const amount = Number(value);

  if (Number.isNaN(amount)) {
    errors.push({
      row: rowNo,
      field: fieldName,
      message: `Row ${rowNo}: ${fieldName} "${value}" is not a number.`,
    });

    return null;
  }

  if (amount <= 0) {
    errors.push({
      row: rowNo,
      field: fieldName,
      message: `Row ${rowNo}: ${fieldName} must be greater than zero.`,
    });

    return null;
  }

  return amount;
}

function validateRequiredAmountByTemplate(row, uploadedFields, errors) {
  const rowNo = row.__rowNumber;

  const uploadedAmountFields = AMOUNT_FIELDS.filter(function (field) {
    return hasField(uploadedFields, field);
  });

  if (!uploadedAmountFields.length) {
    errors.push({
      row: rowNo,
      field: "amount",
      message: `Row ${rowNo}: The uploaded template does not contain any supported amount column.`,
    });

    return {};
  }

  const parsedAmounts = {};
  let hasAtLeastOneAmount = false;

  uploadedAmountFields.forEach(function (field) {
    const amount = parsePositiveAmount(row, field, errors);

    if (amount !== null) {
      parsedAmounts[field] = amount;
      hasAtLeastOneAmount = true;
    }
  });

  /*
   * For templates with only one amount column, this makes that one amount required.
   * For JKEW templates with multiple amount columns, at least one amount is required.
   */
  if (!hasAtLeastOneAmount) {
    errors.push({
      row: rowNo,
      field: "amount",
      message: `Row ${rowNo}: At least one amount column is required.`,
    });
  }

  return parsedAmounts;
}

function validateRow(row, uploadedFields) {
  const errors = [];
  const rowNo = row.__rowNumber;

  const srNo = toTrimmedString(row.srNo);
  const costCentre = toTrimmedString(row.costCentre);
  const glAccount = toTrimmedString(row.glAccount);
  const material = toTrimmedString(row.material);
  const wbs = toTrimmedString(row.wbs);
  const description = toTrimmedString(row.description);

  /*
   * Common optional validation.
   * If you want any of these to be mandatory, add required checks here.
   */
  let assetStatus = toTrimmedString(row.assetStatus);

  if (assetStatus) {
    assetStatus = assetStatus.toUpperCase();

    if (!VALID_ASSET_STATUS.includes(assetStatus)) {
      errors.push({
        row: rowNo,
        field: "assetStatus",
        message: `Row ${rowNo}: Asset Status "${assetStatus}" is invalid (allowed: N/A/R).`,
      });
    }
  }

  if (description && description.length > 255) {
    errors.push({
      row: rowNo,
      field: "description",
      message: `Row ${rowNo}: Description exceeds 255 characters.`,
    });
  }

  const parsedAmounts = validateRequiredAmountByTemplate(
    row,
    uploadedFields,
    errors,
  );

  if (errors.length) {
    return {
      item: null,
      errors: errors,
    };
  }

  /*
   * Return the exact fields needed by the RequestItems table/UI.
   *
   * assetStatus is mapped to assetStatus_code because CAP managed code lists
   * usually use the generated foreign key field.
   */
  return {
    item: {
      srNo: srNo,
      costCentre: costCentre,
      glAccount: glAccount,
      material: material,
      wbs: wbs,
      assetStatus_code: assetStatus,
      supplementAmount: parsedAmounts.supplementAmount || null,
      returnAmount: parsedAmounts.returnAmount || null,
      transferInAmount: parsedAmounts.transferInAmount || null,
      transferOutAmount: parsedAmounts.transferOutAmount || null,
      description: description,
    },
    errors: [],
  };
}

function isActiveEntity(request) {
  const params = request.params || [];
  const last = params[params.length - 1] || {};

  return last.IsActiveEntity === true || last.IsActiveEntity === "true";
}

function reportValidationErrors(request, allErrors) {
  const shown = allErrors.slice(0, MAX_ERRORS_SHOWN);
  const remaining = allErrors.length - shown.length;

  for (const err of shown) {
    request.error(400, err.message, `items/${err.row}/${err.field}`);
  }

  if (remaining > 0) {
    request.error(
      400,
      `There are ${remaining} more validation error(s). Please correct the upload file and try again.`,
      "items",
    );
  }

  /*
   * Important:
   * Do not request.reject("Upload validation failed.") here.
   * Returning after request.error(...) lets CAP reject with collected details.
   */
  return;
}

module.exports = async function uploadItems(request) {
  LOG.info("--- ON uploadItems Requests.drafts started ---");

  try {
    const { content } = request.data;

    if (!content) {
      return request.error(400, "No file content was provided.");
    }

    if (content.length > MAX_BASE64_LENGTH) {
      return request.error(
        400,
        "The uploaded file is too large. Please reduce the number of rows.",
      );
    }

    if (isActiveEntity(request)) {
      return request.error(
        400,
        "Items can only be uploaded while editing the request.",
      );
    }

    let parseResult;

    try {
      parseResult = parseExcel(content);
    } catch (parseError) {
      LOG.error("Excel parsing failed:", parseError);

      return request.error(
        400,
        "Could not read the Excel file. Please use the provided template.",
      );
    }

    const rows = parseResult.rows;
    const uploadedFields = parseResult.uploadedFields;

    if (rows.length === 0) {
      return request.error(
        400,
        "The uploaded file contains no data rows. Please fill in the template and try again.",
      );
    }

    LOG.info(`Parsed ${rows.length} data row(s) from upload.`);
    LOG.info("Detected template fields: " + JSON.stringify(uploadedFields));

    const validItems = [];
    const allErrors = [];

    for (const row of rows) {
      const { item, errors } = validateRow(row, uploadedFields);

      if (errors.length) {
        allErrors.push(...errors);
      } else {
        validItems.push(item);
      }
    }

    if (allErrors.length) {
      LOG.warn(`Validation failed with ${allErrors.length} error(s).`);
      return reportValidationErrors(request, allErrors);
    }

    let nextSr = 1;

    for (const item of validItems) {
      if (!item.srNo) {
        item.srNo = String(nextSr).padStart(SR_NO_PAD_LENGTH, "0");
      }

      nextSr++;
    }

    LOG.info(`Returning ${validItems.length} validated item(s) to the UI.`);
    LOG.info("--- ON uploadItems Requests.drafts ended successfully ---");

    return {
      items: validItems,
    };
  } catch (error) {
    if (
      error &&
      (error.status === 400 ||
        error.statusCode === 400 ||
        error.code === 400 ||
        error.code === "400")
    ) {
      throw error;
    }

    LOG.error("uploadItems failed unexpectedly:", error);

    return request.error(500, "Failed to process the uploaded file.");
  }
};
